'use strict';
const data=window.ANX_DATA;
const grid=document.querySelector('#resource-grid');
const search=document.querySelector('#search');
const resourceDialog=document.querySelector('#resource-dialog');
const infoDialog=document.querySelector('#info-dialog');
let activeCategory='all';
const labels={skills:'CHATGPT SKILL',prompts:'AI PROMPTS',templates:'CAPCUT TEMPLATE'};
const el=(tag,className,text)=>{const node=document.createElement(tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node;};
function render(){const q=search.value.trim().toLowerCase();const results=data.resources.filter(r=>(activeCategory==='all'||r.category===activeCategory)&&[r.title,r.description,r.overview,r.category].join(' ').toLowerCase().includes(q));grid.replaceChildren();for(const r of results){const card=el('article','card');const img=el('img','card-image');img.src=r.image;img.alt=r.title+' visual preview';img.loading='lazy';img.width=552;img.height=344;const copy=el('div','card-copy');const badge=el('span','badge '+r.category,labels[r.category]);const title=el('h3','',r.title);const desc=el('p','',r.description);const button=el('button','','View resource ↗');button.setAttribute('aria-label','View '+r.title);button.addEventListener('click',()=>{location.hash='resource/'+r.slug;});copy.append(badge,title,desc,button);card.append(img,copy);grid.append(card);}document.querySelector('#empty').hidden=results.length!==0;document.querySelector('#result-count').textContent=results.length+' resources found';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===activeCategory)));}
function filter(category){activeCategory=category;render();}
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>filter(b.dataset.filter)));
document.querySelectorAll('[data-category]').forEach(a=>a.addEventListener('click',()=>{filter(a.dataset.category);document.querySelector('.header nav').classList.remove('open');document.querySelector('.menu-button').setAttribute('aria-expanded','false');}));
search.addEventListener('input',render);document.querySelector('.search').addEventListener('submit',e=>{e.preventDefault();render();location.hash='library';});
document.querySelectorAll('[data-social]').forEach(a=>{a.href=data.socials[a.dataset.social];a.target='_blank';a.rel='noopener noreferrer';});
document.querySelector('.menu-button').addEventListener('click',e=>{const open=document.querySelector('.header nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
function openResource(r){const body=document.querySelector('#detail-body');body.replaceChildren();const badge=el('span','badge '+r.category,labels[r.category]);const title=el('h2','detail-title',r.title);title.id='detail-title';const desc=el('p','detail-text',r.overview);const img=el('img','detail-image');img.src=r.image;img.alt=r.title+' design preview';const heading=el('h3','','What this resource covers');const list=el('ul');r.features.forEach(f=>list.append(el('li','',f)));const use=el('h3','','How to use it');const how=el('p','detail-text',r.howToUse);const access=el('div','access-box');access.append(el('strong','','Preview resource'));access.append(el('p','detail-text','The actual resource files have not been connected yet.'));body.append(badge,title,desc,img,heading,list,use,how,access);if(!resourceDialog.open)resourceDialog.showModal();}
function route(){const slug=location.hash.replace('#resource/','');if(location.hash.startsWith('#resource/')){const r=data.resources.find(r=>r.slug===slug);if(r)openResource(r);else location.hash='library';}else if(resourceDialog.open)resourceDialog.close();}
resourceDialog.querySelector('.close').addEventListener('click',()=>resourceDialog.close());resourceDialog.addEventListener('close',()=>{if(location.hash.startsWith('#resource/'))history.replaceState(null,'',location.pathname+location.search+'#library');});
const info={about:['About ANX Studio','ANX Studio makes digital ideas easier to understand through visual lessons and practical creative resources. This local preview presents six resource concepts for the planned English-language library.'],contact:['Contact','You can reach ANX Studio through the linked Instagram, TikTok, and YouTube profiles. A dedicated contact address can be added before launch.'],privacy:['Privacy — draft for review','This local preview does not include analytics, tracking cookies, account registration, or a backend. External platforms have their own privacy practices. Replace this draft with a policy that accurately describes the production services before launching.'],terms:['Terms — draft for review','The six resource cards are previews. No downloadable skill package, prompt collection, or working CapCut template is supplied by this website preview. Publish resources only when the files, permissions, compatibility requirements, and access conditions are verified. Replace this draft with terms appropriate to the final service before launch.']};
document.querySelectorAll('[data-info]').forEach(b=>b.addEventListener('click',()=>{const [title,text]=info[b.dataset.info];const body=document.querySelector('#info-body');body.replaceChildren();const h=el('h2','',title);h.id='info-title';body.append(h,el('p','detail-text',text));infoDialog.showModal();}));infoDialog.querySelector('.close').addEventListener('click',()=>infoDialog.close());
for(const dialog of [resourceDialog,infoDialog])dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
window.addEventListener('hashchange',route);render();route();
